  function skeleton() {
    var view = document.querySelector('#view');
    if (!view) return;
    view.innerHTML = '<div class="empty" style="padding-top:120px"><div class="spinner" style="margin:0 auto 14px"></div><h4>正在载入…</h4></div>';
  }

  var REMEMBER_KEY = 'lantai.remember';

