/* ---- 路由 ---- */
function go(p, replace) {
  if (p === S.route && !replace) return;
  if (S.reader && p.indexOf('/read/') !== 0) closeReader(false);
  if (window.ComicReader && ComicReader.isOpen() && p.indexOf('/read/') !== 0) ComicReader.close(false);
  if (window.EbookReader && EbookReader.isOpen() && p.indexOf('/read/') !== 0) EbookReader.close(false);
  S.route = p;
  (replace ? history.replaceState : history.pushState).call(history, null, '', '#' + p);
  render();
}
function parseHash() {
  const h = location.hash.slice(1) || '/home', q = h.indexOf('?');
  const path = q < 0 ? h : h.slice(0, q), qs = {};
  if (q >= 0) h.slice(q + 1).split('&').forEach(kv => { const [k, v] = kv.split('='); if (k) qs[k] = decodeURIComponent(v || ''); });
  return { path, qs };
}
function catalogReady() {
  return !!(window.LantaiRuntime && LantaiRuntime.catalogReady && LantaiRuntime.catalogReady());
}
function catalogTotal() {
  if (window.LantaiRuntime && LantaiRuntime.catalogTotal) return LantaiRuntime.catalogTotal();
  return { series: SERIES.length, books: BOOKS.length, seriesDone: true, booksDone: true };
}
function ensureCatalog(kind, view) {
  const T = catalogTotal();
  if (kind === 'series' ? T.seriesDone : T.booksDone) return null;
  if (view.getAttribute('data-catfull') === kind) return true;
  view.setAttribute('data-catfull', kind);
  view.innerHTML = '<div class="empty" style="padding-top:120px"><div class="spinner" style="margin:0 auto 14px"></div><h4>' +
    (kind === 'series' ? '正在载入全部系列…' : '正在载入全部书籍…') + '</h4><p>筛选与检索需要完整目录，仅此一次。</p></div>';
  LantaiRuntime.catalogFull(kind).then(() => { view.removeAttribute('data-catfull'); render(); });
  return true;
}
function render() {
  const { path, qs } = parseHash();
  const routeChanged = S.route !== path;
  S.route = path; S.qs = qs || {};
  if (LOGS.src && path.indexOf('/logs') !== 0) { LOGS.src.close(); LOGS.src = null; LOGS.follow = false; }
  if (!location.hash) { document.title = '兰台 Lantai'; }
  renderNav();
  const seg = path.split('/').filter(Boolean);
  const key = Routes[seg[0]] ? seg[0] : 'home';
  const view = $('#view');
  const keepScroll = window.__lantaiKeepScroll === true;
  window.__lantaiKeepScroll = false;
  if (routeChanged && !keepScroll) view.scrollTop = 0;
  if ((key === 'browse' || key === 'search') && !catalogReady()) {
    document.body.classList.remove('has-dock');
    if (view.getAttribute('data-cat') !== path) {
      view.setAttribute('data-cat', path);
      view.innerHTML = '<div class="empty" style="padding-top:120px"><div class="spinner" style="margin:0 auto 14px"></div><h4>正在载入书库…</h4></div>';
      if (window.LantaiRuntime) LantaiRuntime.hydrateCatalog();
    }
    return;
  }
  view.removeAttribute('data-cat');
  view.innerHTML = '';
  try {
    Routes[key](view, seg.slice(1), qs);
  } catch (e) {
    view.insertAdjacentHTML('beforeend', '<div class="card" style="margin-top:18px"><div class="note red">' + ico('alert') + ' 页面渲染出错：' + esc(e && e.message ? e.message : String(e)) + '</div></div>');
    if (window.console && console.error) console.error(e);
  }
  document.body.classList.toggle('has-dock', !!view.querySelector('.pager-dock'));
  syncToTop();
}
function syncToTop() {
  const v = $('#view'), b = document.getElementById('toTop');
  if (!v || !b) return;
  b.classList.toggle('on', v.scrollTop > 120);
}
window.__lantaiOnCatalog = function () {
  const p = S.route || '/home';
  if (p === '/home' || p === '/browse' || p.indexOf('/browse/') === 0 || p === '/search') render();
};
window.addEventListener('hashchange', render);

const SHELF_CHUNK = 80;
function chunkList(list, renderOne) {
  return { head: list.slice(0, SHELF_CHUNK).map(renderOne).join(''), list: list, i: SHELF_CHUNK, renderOne: renderOne };
}
function mountChunked(view, chunk, kind) {
  const el = view.querySelector('[data-chunk]');
  if (!el) return;
  el._more = chunk.list.length > chunk.i ? { list: chunk.list, i: chunk.i, renderOne: chunk.renderOne } : null;
  el._kind = kind || null;
}
$('#view').addEventListener('scroll', function () {
  const el = this.querySelector('[data-chunk]');
  if (!el || el._busy) return;
  if (this.scrollTop + this.clientHeight < this.scrollHeight - 600) return;
  if (el._more) {
    const m = el._more;
    const next = m.list.slice(m.i, m.i + SHELF_CHUNK);
    m.i += SHELF_CHUNK;
    el.insertAdjacentHTML('beforeend', next.map(m.renderOne).join(''));
    if (typeof wire === 'function') wire(el);
    if (m.i >= m.list.length) el._more = null;
    return;
  }
  if (!el._kind) return;
  const T = catalogTotal();
  if (el._kind === 'series' ? T.seriesDone : T.booksDone) return;
  el._busy = true;
  const top = this.scrollTop;
  LantaiRuntime.catalogMore(el._kind).then(() => {
    render();
    $('#view').scrollTop = top;
  });
});

/* ---- toast ---- */
function toast(msg, type, ms) {
  const el = document.createElement('div');
  el.className = 'toast ' + (type || 'info');
  const ic = type === 'ok' ? 'check' : type === 'err' ? 'alert' : 'info';
  const col = type === 'ok' ? 'var(--ok)' : type === 'err' ? 'var(--bad)' : 'var(--acc)';
  el.innerHTML = '<span style="color:' + col + '">' + '<svg class="tic"><use href="#i-' + ic + '"/></svg></span><span>' + esc(msg) + '</span>';
  $('#toasts').appendChild(el);
  setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 260); }, ms || 2600);
}
/* ---- modal / drawer ---- */
let modalOnClose = null;
function openModal(o) {
  $('#mTitle').innerHTML = o.title || '';
  $('#mHead').innerHTML = o.head || '';
  $('#mBody').innerHTML = o.body || '';
  $('#mFoot').innerHTML = o.foot || '';
  $('#modal').style.setProperty('--mw', (o.width || 540) + 'px');
  $('#veil').classList.add('on'); $('#modal').classList.add('on');
  modalOnClose = o.onClose || null;
  if (o.after) o.after();
}
function closeModal() {
  $('#modal').classList.remove('on');
  if (!$('#drawer').classList.contains('on')) $('#veil').classList.remove('on');
  if (modalOnClose) { modalOnClose(); modalOnClose = null; }
}
function openDrawer(o) {
  $('#dTitle').innerHTML = o.title || '';
  $('#dHead').innerHTML = (o.head || '') + '<button class="icon-btn" data-x><svg><use href="#i-close"/></svg></button>';
  $('#dBody').innerHTML = o.body || '';
  $('#drawer').style.setProperty('--dw', (o.width || 440) + 'px');
  $('#veil').classList.add('on'); $('#drawer').classList.add('on');
  $('#drawer').querySelector('[data-x]').onclick = closeDrawer;
  if (o.after) o.after();
}
function closeDrawer() {
  $('#drawer').classList.remove('on');
  if (!$('#modal').classList.contains('on')) $('#veil').classList.remove('on');
}
$('#veil').onclick = () => { closeModal(); closeDrawer(); };

/* ---- 主题 ---- */
function setTheme(t) {
  S.theme = t;
  document.documentElement.dataset.theme = t;
  $('#themeBtn').innerHTML = '<svg><use href="#i-' + (t === 'dark' ? 'sun' : 'moon') + '"/></svg>';
  try { localStorage.setItem('lantai-theme', t); } catch (e) { }
  if (S.reader) applyReaderTheme();
}

/* ---- 心跳（演示节奏：5s 一次，协议为 30s） ---- */
let HB = null, hbSentAt = 0;
function hbTick() {
  if (!S.reader) return;
  const r = S.reader;
  r.beats++;
  r.session.dur += (S.demoFast ? 5e3 : 3e4);
  r.session.pages = Math.max(r.session.pages, r.seen || 0);
  pushSession(r.session);
  paintHb();
  if (r.type === 'reader-stats') render();
  const gap = Math.max(10, CFG.heartbeat || 30) * 1000;
  if (Date.now() - hbSentAt >= gap) sendHeartbeat(r);
}
function sendHeartbeat(r) {
  if (!r || !window.LantaiRuntime) return;
  hbSentAt = Date.now();
  LantaiRuntime.request('api/lantai/v1/reading/heartbeat', {
    method: 'POST',
    body: { bookId: r.bookId, page: r.page, deviceId: 'webui', deviceName: '网页端', client: 'lantai-webui' }
  }).catch(() => { });
}
function stopHeartbeat(r) {
  if (!r || !window.LantaiRuntime) return Promise.resolve();
  return LantaiRuntime.request('api/lantai/v1/reading/stop', {
    method: 'POST',
    body: { bookId: r.bookId, deviceId: 'webui' }
  }).catch(() => { });
}
function paintHb() {
  const r = S.reader; if (!r) return;
  const el = $('#hbLive'); if (el) el.textContent = '计时 ' + durShort(r.session.dur) + ' · 记录 ' + r.beats + ' 次';
  const lr = $('#liveReading');
  if (lr) lr.innerHTML = '<span class="hb" style="padding:5px 11px;border:1px solid var(--acc-line);border-radius:99px;background:var(--acc-bg)">' +
    '<i></i>正在阅读 · ' + esc(series(book(r.bookId).s).t) + ' ' + durShort(r.session.dur) + '</span>';
}
const liveSessions = [];
function pushSession(sess) {
  let ex = liveSessions.find(x => x.id === sess.id);
  if (ex) Object.assign(ex, sess); else liveSessions.push(sess);
  S.sessionExtra = liveSessions.reduce((a, b) => a + b.dur, 0);
}
function startHeartbeat(r) {
  clearInterval(HB);
  HB = setInterval(hbTick, 5000);
  setTimeout(hbTick, 1200);
}

/* ---- 全局搜索 ---- */
function doSearch(q) {
  q = (q || '').trim();
  if (!q) return { series: [], books: [], coll: [], lists: [], online: [] };
  const lq = q.toLowerCase(), m = (s) => String(s || '').toLowerCase().includes(lq);
  return {
    series: SERIES.filter(s => m(s.t) || m(s.author) || (s.tags || []).some(m) || (s.genres || []).some(m)),
    books: BOOKS.filter(b => m(b.name)),
    coll: COLLECTIONS.filter(c => m(c.name)),
    lists: READLISTS.filter(r => m(r.name)),
    online: SERIES.filter(s => s.online && m(s.t))
  };
}
function hlq(text, q) { if (!q) return esc(text); const i = text.toLowerCase().indexOf(q.toLowerCase()); return i < 0 ? esc(text) : esc(text.slice(0, i)) + '<span class="hlq">' + esc(text.slice(i, i + q.length)) + '</span>' + esc(text.slice(i + q.length)); }

