function bulkBarHtml(n) {
  return '<div class="bulkbar">' +
    '<div class="bulkbar-top"><span class="mini">已选 <b>' + n + '</b> 个系列</span><span class="mini" id="bulkProg"></span>' +
    '<button class="btn xs ghost" data-bulk="clear" style="margin-left:auto">取消选择</button></div>' +
    '<div class="bulkbar-row">' +
    '<button class="btn sm pri" data-bulk="download">' + ico('dl') + '批量下载</button>' +
    '<button class="btn sm" data-bulk="reparse">' + ico('wand') + '重新解析</button>' +
    '<button class="btn sm" data-bulk="enqueue">' + ico('list') + '加入刮削名单</button>' +
    '<button class="btn sm danger" data-bulk="exclude">' + ico('trash') + '移出书库</button>' +
    '</div>' +
    '<div class="bulkbar-row soft">' +
    '<button class="btn xs ghost" data-bulk="read">标记已读</button>' +
    '<button class="btn xs ghost" data-bulk="unread">标记未读</button>' +
    '<button class="btn xs ghost" data-bulk="coll">加入合集</button>' +
    '<button class="btn xs ghost" data-bulk="list">加入清单</button>' +
    '<button class="btn xs ghost" data-bulk="del">删除文件</button>' +
    '</div></div>';
}

function bulkAction(kind) {
  const ids = Object.keys(S.browse.sel).filter(id => series(id));
  if (!ids.length) return toast('先选系列', 'err');
  if (kind === 'clear') { S.browse.sel = {}; return render(); }
  if (!window.LantaiRuntime) return toast('后端不可用', 'err');
  if (kind === 'read' || kind === 'unread') {
    const m = kind === 'read' ? 'POST' : 'DELETE';
    return Promise.all(ids.map(id => LantaiRuntime.request('api/v1/series/' + id + '/read-progress', { method: m }).catch(() => null)))
      .then(res => {
        const ok = res.filter(x => x !== null).length;
        toast('已处理 ' + ok + ' / ' + ids.length + ' 个系列', ok === ids.length ? 'ok' : 'warn');
        S.browse.sel = {};
        return LantaiRuntime.hydrate();
      }).then(() => render());
  }
  if (kind === 'coll') return pickTarget('coll', ids);
  if (kind === 'list') return pickTarget('list', ids.flatMap(sid => booksOf(sid).map(b => b.id)));
  if (kind === 'del') return bulkDelete(ids);
  if (kind === 'download') return bulkDownload(ids);
  if (kind === 'reparse') return bulkReparse(ids);
  if (kind === 'enqueue') return bulkScrape(ids, false);
  if (kind === 'exclude') return bulkExclude(ids);
}

function bulkProg(text) {
  const el = $('#bulkProg');
  if (el) el.textContent = text || '';
}

function bulkDownload(ids) {
  if (!catalogTotal().booksDone) {
    toast('正在载入全部书籍，请稍候…', 'info');
    return LantaiRuntime.catalogFull('books').then(() => bulkDownload(ids));
  }
  const items = [];
  let skipped = 0;
  ids.forEach(sid => {
    const bs = booksOf(sid);
    if (!bs.length && series(sid) && series(sid).online) { skipped++; return; }
    bs.forEach(b => {
      if (isOnlineBook(b) && b.downloaded === false) { skipped++; return; }
      items.push(b);
    });
  });
  if (!items.length) return toast('所选系列没有可下载的文件' + (skipped ? '，在线未存档章节需先存档' : ''), 'err', 3600);
  const LIMIT = 60;
  const cut = Math.min(items.length, LIMIT);
  openModal({
    title: '批量下载', width: 480,
    body: '<div class="note">按原始格式逐个下载 <b>' + cut + '</b> 个文件（epub / txt / cbz / pdf 原样，图片文件夹打包为 zip）。</div>' +
      (skipped ? '<div class="note gold" style="margin-top:10px">跳过 ' + skipped + ' 个在线未存档章节，需要先在书籍详情里存档为 CBZ。</div>' : '') +
      (items.length > LIMIT ? '<div class="note red" style="margin-top:10px">本次选中 ' + items.length + ' 个文件，超过单批上限 ' + LIMIT + '。先下载前 ' + LIMIT + ' 个，其余请分批。</div>' : '') +
      '<div class="note" style="margin-top:10px">浏览器会询问「允许下载多个文件」，请点允许。</div>',
    foot: '<button class="btn" data-x>取消</button><button class="btn pri" data-ok>开始下载 ' + cut + ' 个</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        closeModal();
        let i = 0;
        const step = () => {
          if (i >= cut) { bulkProg(''); toast('已发起 ' + cut + ' 个文件下载', 'ok', 3600); return; }
          const b = items[i++];
          bulkProg('下载 ' + i + ' / ' + cut);
          const a = document.createElement('a');
          a.href = 'api/v1/books/' + b.id + '/file';
          a.rel = 'noopener';
          document.body.appendChild(a);
          a.click();
          a.remove();
          setTimeout(step, 420);
        };
        step();
      };
    }
  });
}

function bulkReparse(ids) {
  openModal({
    title: '重新解析', width: 480,
    body: '<div class="note">对 <b>' + ids.length + '</b> 个系列重新读取文件内元数据与封面，并重新分析文件结构。已在解析中的书会跳过。</div>' +
      '<div class="note gold" style="margin-top:10px">任务在后台排队执行，系列较多时需要几分钟。</div>',
    foot: '<button class="btn" data-x>取消</button><button class="btn pri" data-ok>开始解析</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        closeModal();
        let i = 0, ok = 0, bad = 0;
        const step = () => {
          if (i >= ids.length) {
            bulkProg('');
            toast('已提交 ' + ok + ' / ' + ids.length + ' 个系列' + (bad ? '，失败 ' + bad : ''), bad ? 'warn' : 'ok', 3600);
            return;
          }
          const id = ids[i++];
          bulkProg('解析 ' + i + ' / ' + ids.length);
          Promise.all([
            LantaiRuntime.request('api/v1/series/' + id + '/metadata/refresh', { method: 'POST' }).then(() => true).catch(() => false),
            LantaiRuntime.request('api/v1/series/' + id + '/analyze', { method: 'POST' }).then(() => true).catch(() => false)
          ]).then(res => { if (res[0] && res[1]) ok++; else bad++; setTimeout(step, 80); });
        };
        step();
      };
    }
  });
}

function bulkScrape(ids, run) {
  const label = run ? '重新刮削' : '加入刮削名单';
  openModal({
    title: label, width: 480,
    body: '<div class="note">把 <b>' + ids.length + '</b> 个系列' + (run ? '加入刮削名单并立即开始刮削。' : '加入刮削名单，稍后在刮削页统一开始刮削。') + '</div>' +
      '<div class="note gold" style="margin-top:10px">' + (run ? '会消耗元数据源配额，已存在的名单项会被跳过。' : '只登记不请求，开始刮削时才消耗配额。') + '</div>',
    foot: '<button class="btn" data-x>取消</button><button class="btn pri" data-ok>' + (run ? '开始刮削' : '加入名单') + '</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        const btn = $('#modal [data-ok]');
        btn.disabled = true;
        LantaiRuntime.request('api/lantai/v1/scrape/queue', { method: 'POST', body: { seriesIds: ids, run: run } })
          .then(r => {
            closeModal();
            scPage = null;
            toast('已加入 ' + r.added + ' 个' + (r.skipped ? '，跳过 ' + r.skipped + ' 个已在名单' : '') + (run ? '，正在刮削…' : ''), 'ok', 3600);
            S.browse.sel = {};
            render();
          })
          .catch(e => { btn.disabled = false; toast('提交失败：' + onlineErrText(e), 'err'); });
      };
    }
  });
}

function bulkExclude(ids) {
  const onlineCount = ids.filter(id => series(id) && series(id).online).length;
  const localCount = ids.length - onlineCount;
  openModal({
    title: '移出书库', width: 500,
    body: '<div class="note">把 <b>' + ids.length + '</b> 个系列移出书库：本地 ' + localCount + ' 个、在线订阅 ' + onlineCount + ' 个。移出后可在回收站找回。</div>' +
      '<label class="sw" style="margin-top:14px"><input type="checkbox" id="bxDel"><i></i><span>同时删除文件（本地移入回收站，在线清除已存档 CBZ）</span></label>' +
      '<div class="note red" style="margin-top:12px">不勾选时只从书库移除，磁盘文件原样保留。</div>',
    foot: '<button class="btn" data-x>取消</button><button class="btn danger" data-ok>确认移出</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        const del = $('#bxDel') && $('#bxDel').checked;
        const btn = $('#modal [data-ok]');
        btn.disabled = true;
        let ok = 0;
        const step = (i) => {
          if (i >= ids.length) {
            closeModal();
            toast('已移出 ' + ok + ' / ' + ids.length + ' 个系列', ok === ids.length ? 'ok' : 'warn', 3600);
            S.browse.sel = {};
            return LantaiRuntime.hydrate().then(() => render());
          }
          const id = ids[i];
          const s = series(id);
          bulkProg('移出 ' + (i + 1) + ' / ' + ids.length);
          if (s && s.online) {
            LantaiRuntime.request('api/lantai/v1/online/series/' + id + '?purgeDownloads=' + (del ? 'true' : 'false'), { method: 'DELETE' })
              .then(() => { ok++; }).catch(() => null).then(() => setTimeout(() => step(i + 1), 120));
            return;
          }
          const delReq = del ? LantaiRuntime.request('api/v1/series/' + id + '/file', { method: 'DELETE' }).catch(() => null) : Promise.resolve();
          delReq
            .then(() => LantaiRuntime.request('api/lantai/v1/trash/excluded/' + id, { method: 'PUT' }))
            .then(() => { ok++; })
            .catch(() => null)
            .then(() => setTimeout(() => step(i + 1), 120));
        };
        step(0);
      };
    }
  });
}

function pickTarget(kind, ids) {
  if (!ids.length) return toast('没有可加入的条目', 'err');
  const path = kind === 'coll' ? 'api/v1/collections' : 'api/v1/readlists';
  const label = kind === 'coll' ? '合集' : '阅读清单';
  LantaiRuntime.request(path + '?unpaged=true').then(p => {
    const list = unwrapPage(p);
    openModal({
      title: '加入' + label, width: 480,
      body: list.length ? list.map(x => '<div class="list-i"><span class="gi">' + ico(kind === 'coll' ? 'collection' : 'readlist') + '</span>' +
        '<div style="flex:1;min-width:0"><div class="gt">' + esc(x.name) + '</div><div class="gs mini">现有 ' + ((kind === 'coll' ? x.seriesIds : x.bookIds) || []).length + ' 项</div></div>' +
        '<button class="btn xs" data-pick="' + x.id + '">加入</button></div>').join('')
        : '<div class="mini">还没有' + label + '，先到' + label + '页新建一个。</div>' +
        '<div class="note" style="margin-top:10px">本次将加入 ' + ids.length + ' 项。</div>',
      foot: '<button class="btn" data-x>关闭</button>',
      after() {
        $('#modal [data-x]').onclick = closeModal;
        $$('#modal [data-pick]').forEach(el => el.onclick = () => {
          const target = list.find(x => x.id === el.dataset.pick);
          const cur = (kind === 'coll' ? target.seriesIds : target.bookIds) || [];
          const next = Array.from(new Set(cur.concat(ids)));
          const body = kind === 'coll' ? { seriesIds: next } : { bookIds: next };
          LantaiRuntime.request(path + '/' + target.id, { method: 'PATCH', body: body })
            .then(() => { closeModal(); toast('已加入，共 ' + next.length + ' 项', 'ok'); S.browse.sel = {}; render(); })
            .catch(e => toast('加入失败：' + onlineErrText(e), 'err'));
        });
      }
    });
  }).catch(e => toast('读取失败：' + onlineErrText(e), 'err'));
}

