/* ============================ 在线源（Suwayomi 代理） ============================ */
let onlineResults = null, onlineErr = '', onlineKey = '', onlinePage = 1, onlineHasNext = false;
let onlineSubs = null, subsBusy = false, subsErr = '';
const onlineChapterCache = {};

const ERR_TEXT = { 400: '请求参数不正确', 401: '登录状态已失效', 403: '没有权限执行该操作', 404: '目标不存在或已被删除', 405: '服务端不支持该操作', 409: '存在同名冲突', 413: '内容过大', 422: '内容不符合要求', 429: '操作过于频繁', 500: '服务器内部错误', 502: '服务暂时不可用', 503: '服务暂时不可用', 504: '服务响应超时' };
function stripUpstream(t) {
  let s = String(t || '').trim();
  s = s.replace(/^Suwayomi\s+(?:GraphQL\s+)?responded with (\d{3}) [A-Z_]+(?:\s+for\s+\S+)?$/, '图源服务返回 HTTP $1');
  s = s.replace(/^Suwayomi\s+(?:GraphQL\s+)?request failed for \S+?:\s*/, '图源服务：');
  s = s.replace(/\s+for\s+\/api\/\S+/g, '');
  s = s.replace(/^Suwayomi\s+(?:GraphQL\s+)?/, '图源服务：');
  return s.trim();
}
function serverDetail(msg) {
  if (!msg) return '';
  const s = String(msg).trim();
  if (s.charAt(0) !== '{') { const t = stripUpstream(s); return t.length > 120 ? t.slice(0, 120) + '…' : t; }
  try {
    const m = (JSON.parse(s).message || '').trim();
    if (!m || /^\d{3}\s+[A-Z_]+$/.test(m)) return '';
    const t = stripUpstream(m);
    return t.length > 120 ? t.slice(0, 120) + '…' : t;
  } catch (err) { return ''; }
}
function onlineErrText(e) {
  if (!e) return '请求失败';
  const st = e.status;
  if (st && ERR_TEXT[st]) {
    const d = serverDetail(e.message);
    return ERR_TEXT[st] + '（HTTP ' + st + '）' + (d ? '：' + d : '');
  }
  if (st) return 'HTTP ' + st;
  return '无法连接服务，请检查网络后重试';
}
function sourceName(id) {
  const s = SOURCES.find(x => x.id === id);
  return s ? s.name : (id || '在线源');
}
