function runSubscribe(m) {
  if (!window.LantaiRuntime) return toast('后端不可用', 'err');
  const btn = $('#modal [data-ok]');
  btn.disabled = true; btn.innerHTML = '<span class="spinner" style="margin-right:6px"></span>正在创建…';
  LantaiRuntime.request('api/lantai/v1/online/subscribe', { method: 'POST', body: { sourceId: m.sourceId, mangaId: m.mangaId } })
    .then(r => {
      closeModal();
      toast(r.alreadySubscribed ? '已在订阅：' + r.title : '已订阅《' + r.title + '》，共 ' + num(r.bookCount) + ' 章', 'ok', 4000);
      return refreshOnline().then(() => { renderNav(); go('/series/' + r.seriesId); });
    })
    .catch(e => {
      btn.disabled = false; btn.textContent = '确认订阅';
      toast('订阅失败：' + onlineErrText(e), 'err', 4200);
    });
}
