/* ---- 章节下载 ---- */
function downloadChapter(sid, ch) {
  if (!window.LantaiRuntime) return toast('后端不可用', 'err');
  const s = series(sid);
  openModal({
    title: '下载存档 · ' + (s ? s.t : sid), width: 520,
    body: '<div style="display:flex;align-items:center;gap:10px;padding:6px 0"><span class="spinner"></span>' +
      '<div class="mini">正在请求源站并写入存档，整章下载可能需要数十秒，请勿关闭页面。</div></div>',
    foot: '<button class="btn" data-x>关闭</button>'
  });
  $('#modal [data-x]').onclick = closeModal;
  let target = null;
  LantaiRuntime.request('api/lantai/v1/online/series/' + sid + '/chapters')
    .then(rows => {
      const list = rows || [];
      target = ch ? list.find(r => r.index === ch) : list.find(r => !r.downloaded);
      if (!target) { closeModal(); toast(ch ? '找不到第 ' + ch + ' 话' : '所有章节都已存档', 'info'); return null; }
      if (target.downloaded) { closeModal(); toast('「' + target.title + '」已有存档', 'info'); return null; }
      return LantaiRuntime.request('api/lantai/v1/online/books/' + target.bookId + '/download', { method: 'POST' });
    })
    .then(r => {
      if (!r) return;
      closeModal();
      toast('已存档「' + target.title + '」 · ' + r.pageCount + ' 页 · ' + bytes(r.sizeBytes), 'ok', 4200);
      delete onlineChapterCache[sid];
      return refreshOnline().then(() => render());
    })
    .catch(e => { closeModal(); toast('下载失败：' + onlineErrText(e), 'err', 4200); });
}
function unsubscribe(sid) {
  const s = series(sid);
  const sub = (onlineSubs || []).find(x => x.seriesId === sid);
  openModal({
    title: '退订《' + ((s && s.t) || (sub && sub.title) || sid) + '》', width: 460,
    body: '<div class="note red">' + ico('alert') + ' 退订会删除该系列的占位与章节记录，无法恢复。</div>' +
      '<label style="display:flex;gap:8px;align-items:center;margin:14px 0 4px;font-size:12.5px"><input type="checkbox" id="purgeDl"> 同时删除已下载的存档文件</label>' +
      '<div class="mini">不勾选时，已存档的 CBZ 会保留在磁盘上；阅读进度保留。</div>',
    foot: '<button class="btn" data-x>取消</button><button class="btn danger" data-ok>确认退订</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        if (!window.LantaiRuntime) return toast('后端不可用', 'err');
        const purge = $('#purgeDl').checked;
        const btn = $('#modal [data-ok]');
        btn.disabled = true; btn.innerHTML = '<span class="spinner" style="margin-right:6px"></span>正在退订…';
        LantaiRuntime.request('api/lantai/v1/online/series/' + sid + '?purgeDownloads=' + purge, { method: 'DELETE' })
          .then(() => {
            closeModal();
            toast('已退订', 'ok');
            delete onlineChapterCache[sid];
            return refreshOnline();
          })
          .then(() => { renderNav(); go('/online?tab=subs'); })
          .catch(e => { btn.disabled = false; btn.textContent = '确认退订'; toast('退订失败：' + onlineErrText(e), 'err', 4200); });
      };
    }
  });
}
function syncSeries(sid) {
  if (!window.LantaiRuntime) return toast('后端不可用', 'err');
  toast('正在同步章节…', 'info', 1600);
  LantaiRuntime.request('api/lantai/v1/online/sync/' + sid, { method: 'POST' })
    .then(r => {
      toast('同步完成：新增 ' + r.added + ' · 更新 ' + r.updated + ' · 共 ' + r.total + ' 章', 'ok', 4200);
      delete onlineChapterCache[sid];
      return refreshOnline().then(() => render());
    })
    .catch(e => toast('同步失败：' + onlineErrText(e), 'err', 4200));
}
