    clientSessionId: x.id, bookId: x.book,
    startedAt: new Date(x.start).toISOString(),
    endedAt: new Date(x.end || Date.now()).toISOString(),
    durationMs: x.dur, startPage: 1, lastPage: x.pages || 1,
