function wireScrape() {
  const start = $('#view [data-sc-start]');
  if (start) start.onclick = () => {
    start.disabled = true;
    LantaiRuntime.request('api/lantai/v1/scrape/queue/start', { method: 'POST' })
      .then(r => { toast('已开始刮削 ' + r.started + ' 部', 'ok'); scPollStart(); loadScrape(); })
      .catch(e => { start.disabled = false; toast('启动失败：' + onlineErrText(e), 'err'); });
  };
  const pause = $('#view [data-sc-pause]');
  if (pause) pause.onclick = () => {
    LantaiRuntime.request('api/lantai/v1/scrape/queue/pause', { method: 'POST' })
      .then(() => { toast('已请求暂停，当前条目完成后停止', 'info'); loadScrape(); })
      .catch(e => toast('暂停失败：' + onlineErrText(e), 'err'));
  };
  const rf = $('#view [data-sc-refresh]');
  if (rf) rf.onclick = () => loadScrape();
  const cfg = $('#view [data-sc-settings]');
  if (cfg) cfg.onclick = scSettingsModal;
  $$('#view [data-sc-filter]').forEach(el => el.onclick = () => { scFilter = el.dataset.scFilter; scOffset = 0; scOpen = null; scPreview = null; loadScrape(); });
  $$('#view [data-sc-open]').forEach(el => el.onclick = () => scToggle(el.dataset.scOpen));
  $$('#view [data-sc-retry]').forEach(el => el.onclick = () => scRetry(el.dataset.scRetry));
  $$('#view [data-sc-del]').forEach(el => el.onclick = () => scRemove(el.dataset.scDel));
  $$('#view [data-sc-clear]').forEach(el => el.onclick = () => scClear(el.dataset.scClear));
  $$('#view [data-sc-field]').forEach(el => el.onchange = () => { scPicked[el.dataset.scField] = el.checked; });
  const ap = $('#view [data-sc-apply]');
  if (ap) ap.onclick = () => scResolve(false);
  const apAll = $('#view [data-sc-applyall]');
  if (apAll) apAll.onclick = () => scResolve(true);
  const cl = $('#view [data-sc-close]');
  if (cl) cl.onclick = () => { scOpen = null; scPreview = null; paintScrape(); };
  $$('#scBody [data-go]').forEach(el => el.onclick = () => go(el.dataset.go));
  wirePagerBar($('#view') || document, {
    maxSize: 200,
    onPage: p => { scOffset = (p - 1) * scLimit; scOpen = null; scPreview = null; loadScrape(); },
    onSize: n => { scLimit = n; scOffset = 0; scOpen = null; scPreview = null; loadScrape(); }
  });
}
function scToggle(id) {
  if (scOpen === id) { scOpen = null; scPreview = null; paintScrape(); return; }
  scOpen = id;
  scPreview = null;
  scPicked = {};
  paintScrape();
  LantaiRuntime.request('api/lantai/v1/scrape/queue/' + id + '/diff')
    .then(d => { if (scOpen === id) { scPreview = d; paintScrape(); } })
    .catch(e => toast('差异计算失败：' + onlineErrText(e), 'err', 3600));
}
function scRetry(id) {
  LantaiRuntime.request('api/lantai/v1/scrape/queue/' + id + '/retry', { method: 'POST' })
    .then(() => { toast('已重新排队', 'ok'); scOpen = null; scPreview = null; loadScrape(); })
    .catch(e => toast('重试失败：' + onlineErrText(e), 'err'));
}
function scRemove(id) {
  LantaiRuntime.request('api/lantai/v1/scrape/queue/' + id, { method: 'DELETE' })
    .then(() => { toast('已从名单移除', 'ok'); scOpen = null; scPreview = null; loadScrape(); })
    .catch(e => toast('移除失败：' + onlineErrText(e), 'err'));
}
function scClear(scope) {
  openModal({
    title: scope === 'all' ? '清空整份名单' : '清除待核对条目', width: 440,
    body: '<div class="note ' + (scope === 'all' ? 'red' : '') + '">' + (scope === 'all' ? '所有未完成的刮削记录都会被移除，已应用的元数据不受影响。' : '仅移除待核对的条目，不会改动任何元数据。') + '</div>',
    foot: '<button class="btn" data-x>取消</button><button class="btn ' + (scope === 'all' ? 'danger' : 'pri') + '" data-ok>确认</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      $('#modal [data-ok]').onclick = () => {
        closeModal();
        LantaiRuntime.request('api/lantai/v1/scrape/queue?scope=' + scope, { method: 'DELETE' })
          .then(r => { toast('已清除 ' + r.removed + ' 条', 'ok'); scOpen = null; scPreview = null; loadScrape(); })
          .catch(e => toast('清除失败：' + onlineErrText(e), 'err'));
      };
    }
  });
}
function scResolve(all) {
  if (!scOpen) return;
  const id = scOpen;
  const fields = all ? [] : Object.keys(scPicked).filter(k => scPicked[k]);
  if (!all && !fields.length) return toast('先勾选至少一个字段', 'err');
  LantaiRuntime.request('api/lantai/v1/scrape/queue/' + id + '/resolve', { method: 'POST', body: { fields: fields } })
    .then(r => { toast(r ? '已应用所选字段，仍有字段待核对' : '已应用并移出名单', 'ok'); scOpen = null; scPreview = null; loadScrape(); })
    .catch(e => toast('应用失败：' + onlineErrText(e), 'err', 3600));
}
function scPollStart() {
  if (scPoll) return;
  let n = 0;
  scPoll = setInterval(() => {
    n++;
    if (S.route.indexOf('/scrape') !== 0) { clearInterval(scPoll); scPoll = null; return; }
    loadScrape();
    const c = scCounts();
    if (n > 300 || ((c.queued || 0) + (c.running || 0) === 0)) { clearInterval(scPoll); scPoll = null; }
  }, 2500);
}
function scSettingsModal() {
  scSettingsTab = 'general';
  openModal({
    title: '刮削设置', width: 760,
    body: '<div id="scCfg"></div>',
    foot: '<button class="btn" data-x>关闭</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      paintScSettings();
    }
  });
}
function paintScSettings() {
  const box = $('#scCfg');
  if (!box) return;
  const tabs = [['general', '常规'], ['sources', '数据源'], ['token', '刮削令牌']];
  const s = scSettings || { trustResult: false, batchSize: 20 };
  let html = '<div class="seg" style="margin-bottom:14px">' + tabs.map(t => '<button class="' + (scSettingsTab === t[0] ? 'on' : '') + '" data-sc-tab="' + t[0] + '">' + t[1] + '</button>').join('') + '</div>';
  if (scSettingsTab === 'general') {
    html += '<label class="sw" style="display:flex;align-items:flex-start;gap:10px;padding:8px 0"><input type="checkbox" id="scTrust"' + (s.trustResult ? ' checked' : '') + '><i></i>' +
      '<span><b>信任刮削结果</b><span class="mini" style="display:block;color:var(--tx-3)">开启后冲突字段直接采用候选值，不再进入待核对。批量刮削时省事，但可能写入大量错误数据。</span></span></label>' +
      '<div id="scTrustWarn" class="note red" style="margin:10px 0 0' + (s.trustResult ? '' : ';display:none') + '">⚠️ 开启后不会再有「待核对」拦截，冲突字段会被直接覆盖。确认候选源可信再开启。</div>' +
      '<label class="sw" id="scTrustConfirmBox" style="display:none;align-items:center;gap:10px;margin-top:8px"><input type="checkbox" id="scTrustConfirm"><i></i><span class="mini">我已了解风险，确认开启</span></label>' +
      '<div class="field" style="margin-top:16px"><label>每批处理条数</label><input class="inp" id="scBatch" type="number" min="1" max="200" value="' + (s.batchSize || 20) + '">' +
      '<div class="mini" style="margin-top:6px;color:var(--tx-3)">每批结束刷新一次名单，过大容易出现长时间无反馈。</div></div>' +
      '<div class="rowflex" style="margin-top:16px"><button class="btn pri" data-sc-save>保存设置</button></div>';
  }
  if (scSettingsTab === 'sources') {
    html += '<div id="scSrcBox">' + scSourceListHtml() + '</div>';
  }
  if (scSettingsTab === 'token') {
    const list = scTokens || [];
    html += '<div class="note">刮削令牌只能读取名单与回传刮削结果，权限写死，访问不了书库其他接口。</div>' +
      (list.length
        ? '<div class="tbl-wrap" style="margin-top:12px"><table class="tbl"><thead><tr><th>名称</th><th>令牌</th><th style="width:70px">调用</th><th style="width:120px">创建</th><th style="width:120px"></th></tr></thead><tbody>' +
          list.map(t => '<tr><td>' + esc(t.name) + '</td><td class="mono mini">' + esc(t.value) + '</td><td class="mini">' + (t.useCount || 0) + '</td>' +
            '<td class="mini mono">' + esc(String(t.createdDate || '').slice(0, 16).replace('T', ' ')) + '</td>' +
            '<td style="text-align:right"><button class="btn xs ghost" data-sc-copy="' + esc(t.value) + '">复制</button>' +
            '<button class="btn xs danger" data-sc-tokdel="' + esc(t.id) + '">吊销</button></td></tr>').join('') + '</tbody></table></div>'
        : '<div class="empty" style="padding:22px"><h4>还没有刮削令牌</h4><p>生成后可用于外部抓取脚本或 AI 回填。</p></div>') +
      '<div class="rowflex" style="gap:8px;margin-top:14px"><button class="btn pri" data-sc-toknew>生成刮削令牌</button>' +
      '<button class="btn ghost" data-sc-tokrot>轮换令牌</button></div>' +
      '<div class="note" style="margin-top:12px">与设置中心的 API 管理共用一份数据，吊销后立即失效。</div>';
  }
  box.innerHTML = html;
  $$('#scCfg [data-sc-tab]').forEach(el => el.onclick = () => { scSettingsTab = el.dataset.scTab; paintScSettings(); });
  const trust = $('#scTrust');
  if (trust) trust.onchange = () => {
    const warn = $('#scTrustWarn'), confirmBox = $('#scTrustConfirmBox');
    if (warn) warn.style.display = trust.checked ? '' : 'none';
    if (confirmBox) confirmBox.style.display = trust.checked ? 'flex' : 'none';
  };
  const save = $('#scCfg [data-sc-save]');
  if (save) save.onclick = () => {
    const nextTrust = $('#scTrust') && $('#scTrust').checked;
    const batch = Number($('#scBatch') && $('#scBatch').value) || 20;
    const confirmed = $('#scTrustConfirm') && $('#scTrustConfirm').checked;
    const wasTrust = !!(scSettings && scSettings.trustResult);
    if (nextTrust && !wasTrust && !confirmed) return toast('先勾选「我已了解风险」', 'err');
    LantaiRuntime.request('api/lantai/v1/scrape/settings', { method: 'PATCH', body: { trustResult: nextTrust, batchSize: batch, confirm: nextTrust } })
      .then(v => { scSettings = v; toast('设置已保存', 'ok'); paintScSettings(); loadScrape(); })
      .catch(e => toast('保存失败：' + onlineErrText(e), 'err'));
  };
  $$('#scCfg [data-sc-copy]').forEach(el => el.onclick = () => copyText(el.dataset.scCopy, '令牌'));
  $$('#scCfg [data-sc-tokdel]').forEach(el => el.onclick = () => {
    LantaiRuntime.request('api/lantai/v1/scrape/agent/token/' + el.dataset.scTokdel, { method: 'DELETE' })
      .then(() => { toast('已吊销', 'ok'); return loadScrape(); })
      .then(() => { if ($('#scCfg')) paintScSettings(); })
      .catch(e => toast('吊销失败：' + onlineErrText(e), 'err'));
  });
  const tkNew = $('#scCfg [data-sc-toknew]');
  if (tkNew) tkNew.onclick = () => scTokenCreate(false);
  const tkRot = $('#scCfg [data-sc-tokrot]');
  if (tkRot) tkRot.onclick = () => scTokenCreate(true);
  wireScSources();
}
function scTokenCreate(rotate) {
  LantaiRuntime.request('api/lantai/v1/scrape/agent/token', { method: 'POST', body: { rotate: rotate } })
    .then(t => { toast('已生成刮削令牌', 'ok'); return loadScrape(); })
    .then(() => { if ($('#scCfg')) paintScSettings(); })
    .catch(e => toast('生成失败：' + onlineErrText(e), 'err'));
}
