function loadScSources() {
  if (!window.LantaiRuntime) return;
  scSourceBusy = true;
  LantaiRuntime.request('api/lantai/v1/scrape/sources')
    .then(list => { scSources = Array.isArray(list) ? list : []; scSourceBusy = false; if ($('#scCfg')) paintScSettings(); })
    .catch(e => { scSourceBusy = false; toast('数据源加载失败：' + onlineErrText(e), 'err'); });
}
function wireScSources() {
  const box = $('#scSrcBox');
  if (!box) return;
  if (!scSources && !scSourceBusy) loadScSources();
  box.querySelectorAll('[data-src-toggle]').forEach(el => el.onchange = () => toggleSource(el.dataset.srcToggle, el.checked));
  box.querySelectorAll('[data-src-edit]').forEach(el => el.onclick = () => srcModal(el.dataset.srcEdit));
  box.querySelectorAll('[data-src-del]').forEach(el => el.onclick = () => deleteSource(el.dataset.srcDel));
  box.querySelectorAll('[data-src-test]').forEach(el => el.onclick = () => testSource(el.dataset.srcTest));
  box.querySelectorAll('[data-screset]').forEach(el => el.onclick = () => resetScrapeSource(el.dataset.screset));
  const add = box.querySelector('[data-src-add]');
  if (add) add.onclick = () => srcModal(null);
}
