  if (kind === 'suwayomi' && !d.enabled) return ['已安装 · 未启用', 'warn'];
  if (d.ready) return ['已就绪', 'ok'];
  const libcBad = d.checks && d.checks.some(c => c.name === 'libc' && !c.ok);
