function wireSwyControls(B) {
  B.querySelectorAll('[data-swyact]').forEach(el => el.onclick = () => {
    const act = el.dataset.swyact;
    S.swyPending = act;
    repaintRt('suwayomi');
    LantaiRuntime.request('api/lantai/v1/suwayomi/lifecycle/' + act, { method: 'POST' })
      .then(st => {
        if (st) swyStatus = st;
        toast('在线源服务' + ({ start: '已启动', stop: '已停止', restart: '已重启' }[act] || '状态已更新'), 'ok');
      })
      .catch(e => toast('操作失败：' + onlineErrText(e), 'err'))
      .then(() => { S.swyPending = ''; loadSwy(true); repaintRt('suwayomi'); });
  });
  B.querySelectorAll('[data-swy-refresh]').forEach(el => el.onclick = () => {
    swyStatus = null; swySettings = null; swyStores = null;
    loadSwy(); toast('正在重新读取服务状态');
  });
  const rot = B.querySelector('[data-swy-rotate]'); if (rot) rot.onclick = () => {
    openModal({
      title: '轮换服务密码', width: 460,
      body: '<div class="note red">新密码立即写入配置文件，需重启在线源服务后生效；旧密码随即失效。</div>',
      foot: '<button class="btn" data-x>取消</button><button class="btn pri" data-ok>轮换</button>',
      after() {
        $('#modal [data-x]').onclick = closeModal;
        $('#modal [data-ok]').onclick = () => {
          closeModal();
          LantaiRuntime.request('api/lantai/v1/suwayomi/password/rotate', { method: 'POST' })
            .then(r => toast(r && r.message ? r.message : '密码已轮换，重启服务后生效', 'ok'))
            .catch(e => toast('轮换失败：' + onlineErrText(e), 'err'));
        };
      }
    });
  };
  B.querySelectorAll('[data-swycfg]').forEach(el => el.onchange = () => {
    const key = el.dataset.swycfg, type = el.dataset.swytype;
    let val;
    if (type === 'bool') val = el.checked;
    else if (type === 'num') { val = Number(el.value); if (!isFinite(val)) return toast('请输入数字', 'err'); }
    else val = el.value;
    swyPatch(key, val);
  });
  const addStore = B.querySelector('[data-swyaddstore]'); if (addStore) addStore.onclick = () => {
    openModal({
      title: '添加扩展仓库', width: 520,
      body: '<div class="field"><label>索引地址</label><input class="inp mono" id="swyStoreUrl" placeholder="https://.../index.min.json"></div>' +
        '<div class="note">仓库索引需为 keiyoushi 兼容格式，兰台会同时抓取 jar 与图标字段。</div>',
      foot: '<button class="btn" data-x>取消</button><button class="btn pri" data-ok>添加</button>',
      after() {
        $('#modal [data-x]').onclick = closeModal;
        $('#modal [data-ok]').onclick = () => {
          const url = $('#swyStoreUrl').value.trim();
          if (!url) return toast('请填写索引地址', 'err');
          LantaiRuntime.request('api/lantai/v1/suwayomi/stores', { method: 'POST', body: { indexUrl: url } })
            .then(r => {
              closeModal();
              toast(r && r.message ? r.message : '仓库已添加', r && r.success === false ? 'err' : 'ok');
              swyStores = null; loadSwy();
            })
            .catch(e => toast('添加失败：' + onlineErrText(e), 'err'));
        };
      }
    });
  };
  const test = B.querySelector('[data-test-swy]'); if (test) test.onclick = () => {
    const st = swyStatus;
    openModal({
      title: '在线源服务自检', width: 520,
      body: (st ? kvLine('服务状态', st.running ? '运行中' : '已停止') +
        kvLine('版本', st.version || '未安装') +
        kvLine('已装图源', (st.installedCount || 0) + ' 个 · ' + (st.updatableCount || 0) + ' 个可更新') +
        kvLine('监听地址', st.endpoint || '—') +
        kvLine('配置文件', st.configPath || '—')
        : '<div class="note red">服务状态尚未读取，请先刷新。</div>') +
        '<div class="note gold" style="margin-top:12px">服务由兰台自动管理，无需手动配置。</div>',
      foot: '<button class="btn pri" data-x>关闭</button>', after() { $('#modal [data-x]').onclick = closeModal; }
    });
  };
}
function afterExtChange(msg, bad) {
  rtExts = null; rtCat = null; rtCatTotal = 0; rtCatOffset = 0; rtCatPage = 0;
  srcLoaded = false; srcBusy = false; SOURCES.length = 0;
  swyStatus = null; swySettings = null; swyStores = null;
  if (msg) toast(msg, bad ? 'err' : 'ok');
  loadSources();
  loadSwy();
  return (window.LantaiRuntime ? LantaiRuntime.hydrate().catch(() => {}) : Promise.resolve())
    .then(() => loadExts(true))
    .then(() => repaintExtViews());
}
function wireExt(v) {
  v.querySelectorAll('[data-swytab]').forEach(el => el.onclick = () => go('/extensions/swy/' + el.dataset.swytab));
  const io = v.querySelector('[data-extinstall-open]'); if (io) io.onclick = () => go('/extensions/swy/catalog');
  wireSwyControls(v);
  const upBtn = v.querySelector('[data-extupload]');
  const upFile = v.querySelector('#extFile');
  if (upBtn && upFile) {
    upBtn.onclick = () => upFile.click();
    upFile.onchange = () => {
      const f = upFile.files && upFile.files[0];
      if (!f) return;
      const base = (window.resourceBaseUrl || '/').replace(/\/?$/, '/');
      const fd = new FormData();
      fd.append('file', f);
      upFile.value = '';
      upBtn.disabled = true;
      toast('正在导入 ' + f.name + '（' + bytes(f.size) + '）', 'info', 6000);
      fetch(base + 'api/lantai/v1/suwayomi/extensions/upload', { method: 'POST', credentials: 'same-origin', body: fd })
        .then(r => (r.ok ? r.json() : r.text().then(t => Promise.reject(new Error(t || ('HTTP ' + r.status))))))
        .then(d => { toast((d && d.message) || '插件包已导入', d && d.success === false ? 'warn' : 'ok', 6000); loadExts(true); })
        .catch(e => toast('导入失败：' + (e.message || e), 'err', 9000))
        .then(() => { upBtn.disabled = false; });
    };
  }
  const retry = v.querySelector('[data-extretry]');
  if (retry) retry.onclick = () => { rtCatFailed = false; rtCat = null; loadCat(rtCatPage, true); };
  const rf = v.querySelector('[data-extrefresh]');
  if (rf) rf.onclick = () => {
    rf.disabled = true;
    const host = document.createElement('span');
    host.style.cssText = 'display:inline-flex;align-items:center;gap:8px;font-size:12px;color:var(--tx-3)';
    rf.parentElement.appendChild(host);
    extBusy(host, '刷新已装扩展');
    LantaiRuntime.request('api/lantai/v1/suwayomi/extensions/fetch', { method: 'POST' })
      .then(r => afterExtChange(r && r.message ? r.message : '扩展清单已刷新', r && r.success === false))
      .catch(e => toast('刷新失败：' + onlineErrText(e), 'err'))
      .then(() => { host.remove(); rf.disabled = false; });
  };
  const q = v.querySelector('[data-extq]');
  if (q) q.oninput = () => {
    S.ext.q = q.value;
    clearTimeout(q._t);
    q._t = setTimeout(() => { rtCat = null; rtCatTotal = 0; rtCatOffset = 0; rtCatPage = 0; loadCat(0, true); }, 320);
  };
  v.querySelectorAll('[data-extlang]').forEach(el => el.onclick = () => {
    S.ext.lang = el.dataset.extlang;
    rtCat = null; rtCatTotal = 0; rtCatOffset = 0; rtCatPage = 0;
    loadCat(0, true);
  });
  v.querySelectorAll('[data-extpage]').forEach(el => el.onclick = () => {
    const next = el.dataset.extpage === 'prev' ? rtCatPage - 1 : rtCatPage + 1;
    if (next < 0 || next >= catPages()) return;
    el.disabled = true;
    loadCat(next, true);
  });
  v.querySelectorAll('[data-extinstall]').forEach(el => el.onclick = () => {
    const pkg = el.dataset.extinstall, host = v.querySelector('#extProg-' + pkg) || el.parentElement;
    el.disabled = true; extBusy(host, '安装中');
    LantaiRuntime.request('api/lantai/v1/suwayomi/extensions/' + encodeURIComponent(pkg) + '/install', { method: 'POST' })
      .then(r => afterExtChange(r && r.message ? r.message : pkg + ' 安装完成', r && r.success === false))
      .catch(e => { el.disabled = false; toast('安装失败：' + onlineErrText(e), 'err'); render(); });
  });
  v.querySelectorAll('[data-extupdate]').forEach(el => el.onclick = () => {
    const pkg = el.dataset.extupdate, host = v.querySelector('#extProg-' + pkg) || el.parentElement;
    el.disabled = true; extBusy(host, '更新中');
    LantaiRuntime.request('api/lantai/v1/suwayomi/extensions/' + encodeURIComponent(pkg) + '/update', { method: 'POST' })
      .then(r => afterExtChange(r && r.message ? r.message : pkg + ' 已更新', r && r.success === false))
      .catch(e => { el.disabled = false; toast('更新失败：' + onlineErrText(e), 'err'); render(); });
  });
  v.querySelectorAll('[data-extpref]').forEach(el => el.onclick = () => {
    const pkg = el.dataset.extpref, e = (rtExts || []).find(x => x.pkgName === pkg);
    extPrefsModal(pkg, e ? e.name : pkg);
  });
  v.querySelectorAll('[data-extuninstall]').forEach(el => el.onclick = () => {
    const pkg = el.dataset.extuninstall, e = (rtExts || []).find(x => x.pkgName === pkg);
    const name = e ? (e.name || e.pkgName) : pkg;
    openModal({
      title: '卸载扩展？', width: 470,
      body: '<div class="note red">删除 <b>' + esc(name) + '</b> 后，该图源立即从统一搜索与订阅入口摘除；' +
        '已订阅作品的存档、进度与书签都会保留。</div>',
      foot: '<button class="btn" data-x>取消</button><button class="btn danger" data-ok>卸载</button>',
      after() {
        $('#modal [data-x]').onclick = closeModal;
        $('#modal [data-ok]').onclick = () => {
          closeModal();
          LantaiRuntime.request('api/lantai/v1/suwayomi/extensions/' + encodeURIComponent(pkg), { method: 'DELETE' })
            .then(r => afterExtChange(r && r.message ? r.message : name + ' 已卸载', r && r.success === false))
            .catch(err => toast('卸载失败：' + onlineErrText(err), 'err'));
        };
      }
    });
  });
}

const TASK_PAGE_SIZES = [20, 50, 100, 200];
let taskQ = { data: null, page: 0, size: 50, state: '', type: '', busy: false, err: '', tab: 'queue', open: {}, sub: {}, hist: null, hpage: 0, hsize: 50, hstatus: '', htype: '', hbusy: false, herr: '' };
function loadTaskQueue(silent) {
  if (taskQ.busy || !window.LantaiRuntime) return;
  taskQ.busy = true;
  const q = 'api/lantai/v1/tasks?page=' + taskQ.page + '&size=' + taskQ.size +
    (taskQ.state ? '&state=' + taskQ.state : '') + (taskQ.type ? '&type=' + encodeURIComponent(taskQ.type) : '');
  return LantaiRuntime.request(q)
    .then(d => { taskQ.data = d; taskQ.err = ''; })
    .catch(e => { taskQ.err = onlineErrText(e); })
    .then(() => { taskQ.busy = false; if (!silent && S.route === '/tasks') render(); });
}
function libStatKey() {
  if (!libStats) return '';
  return Object.keys(libStats).sort().map(k => k + '=' + (libStats[k].bookCount || 0) + '/' + (libStats[k].seriesCount || 0)).join(',');
}
function pageFingerprint() {
  const libs = LIBS.map(l => l.id + ':' + l.name + ':' + (l.unavailable ? 1 : 0)).join(';');
  const swy = swyStatus ? [swyStatus.running ? 1 : 0, swyStatus.version || '', swyStatus.updatableCount || 0].join(':') : '';
  const rtd = ['suwayomi', 'calibre'].map(k => {
    const r = S.rt[k] || {}, d = r.detect || {}, p = r.progress || {};
    return k + ':' + (d.installed ? 1 : 0) + (d.usable ? 1 : 0) + (d.ready ? 1 : 0) + ':' + (p.phase || '') + ':' + (p.percent || 0) + ':' + (r.version || '');
  }).join(';');
  const cnt = homeApp.data && homeApp.data.counts ? JSON.stringify(homeApp.data.counts) : '';
  return [libs, TASKS.length, TASKS.filter(t => t.state === 'run').length, SERIES.length, BOOKS.length, swy, rtd, cnt, libStatKey()].join('|');
}
let pageTick = null, pageTickCount = 0;
function pollCurrentPage() {
  if (!window.LantaiRuntime || document.hidden) return Promise.resolve();
  const p = String(S.route || '');
  if (/^\/read\//.test(p)) return Promise.resolve();
  const ae = document.activeElement;
  if (ae && ae.tagName && /INPUT|TEXTAREA|SELECT/.test(ae.tagName)) return Promise.resolve();
  pageTickCount++;
  const before = pageFingerprint();
  const jobs = [];
  if (p === '/home') jobs.push(loadAppHome(true));
  if (p.indexOf('/extensions') === 0) {
    jobs.push(loadSwy(true));
    if (pageTickCount % 3 === 0) { jobs.push(loadExts(true)); rtLoad(); }
  }
  if (p.indexOf('/settings') === 0) {
    jobs.push(loadSysSettings(true, true));
    if (S.settingsTab === 'libraries') jobs.push(loadLibStats(true));
    if (S.settingsTab === 'upgrade') jobs.push(loadUpgrade(true));
    if (S.settingsTab === 'online') jobs.push(loadSwy(true));
  }
  if (p === '/tasks') jobs.push(loadTaskQueue(true));
  if (p === '/online') jobs.push(loadSwy(true));
  return Promise.all(jobs).catch(() => {}).then(() => {
    if (pageFingerprint() !== before && p.indexOf('/extensions') !== 0) render();
  });
}
function startPagePoll() {
  if (pageTick) return;
  pageTick = setInterval(pollCurrentPage, 4000);
}
function loadTaskHistory(silent) {
  if (taskQ.hbusy || !window.LantaiRuntime) return;
  taskQ.hbusy = true;
  const q = ['page=' + taskQ.hpage, 'size=' + taskQ.hsize]
    .concat(taskQ.htype ? ['type=' + encodeURIComponent(taskQ.htype)] : [])
    .concat(taskQ.hstatus ? ['status=' + taskQ.hstatus] : []);
  LantaiRuntime.request('api/lantai/v1/tasks/history?' + q.join('&'))
    .then(d => { taskQ.hist = d; taskQ.herr = ''; })
    .catch(e => { taskQ.hist = null; taskQ.herr = onlineErrText(e); })
    .then(() => { taskQ.hbusy = false; if (!silent && S.route === '/tasks') render(); });
}
function reloadTasksAndQueue() {
  const done = () => { loadTaskQueue(); };
  if (window.LantaiRuntime && LantaiRuntime.hydrateShell) return LantaiRuntime.hydrateShell().catch(() => {}).then(done);
  return Promise.resolve().then(done);
}
