  B.querySelectorAll('[data-idle]').forEach(el => el.onclick = () => { CFG.idleCap = +el.dataset.idle; savePrefs({ idleCap: CFG.idleCap }); toast('空闲判定 ' + el.dataset.idle + ' 秒'); render(); });
