  const nl2 = B.querySelector('[data-newlib2]'); if (nl2) nl2.onclick = () => {
    const n = $('#nlName').value.trim(), r = $('#nlRoot').value.trim();
    if (!n || !r) return toast('名称与根目录都要填', 'err');
    nl2.disabled = true;
    LantaiRuntime.request('api/v1/libraries', { method: 'POST', body: { name: n, root: r } })
      .then(() => { $('#nlName').value = ''; $('#nlRoot').value = ''; return libReload('已建库 ' + n + '，首次扫描已入队'); })
      .catch(e => toast('建库失败：' + onlineErrText(e), 'err'))
      .then(() => { nl2.disabled = false; });
  };
