function historyModal(page) {
  const p = page || 0;
  openModal({
    title: '操作历史', width: 720,
    body: '<div id="histBody"><div class="mini" style="padding:14px 0">正在读取…</div></div>',
    foot: '<button class="btn" data-x>关闭</button>',
    after() {
      $('#modal [data-x]').onclick = closeModal;
      LantaiRuntime.request('api/v1/history?page=' + p + '&size=30')
        .then(d => {
          const rows = (d && d.content) || [];
          const box = $('#histBody');
          if (!box) return;
          if (!rows.length) { box.innerHTML = '<div class="mini" style="padding:14px 0">没有记录。</div>'; return; }
          box.innerHTML = '<div class="tbl-wrap"><table class="tbl"><thead><tr><th>时间</th><th>类型</th><th>对象</th><th>用户</th></tr></thead><tbody>' +
            rows.map(h => '<tr><td class="mono mini">' + esc(String(h.timestamp || '').replace('T', ' ').slice(0, 19)) + '</td>' +
              '<td><span class="badge">' + esc(h.type || '—') + '</span></td>' +
              '<td class="mini">' + esc([h.properties && h.properties.series, h.properties && h.properties.book, h.properties && h.properties.library].filter(Boolean).join(' · ') || h.properties && h.properties.name || '—') + '</td>' +
              '<td class="mini">' + esc(h.properties && h.properties.user || '—') + '</td></tr>').join('') +
            '</tbody></table></div>' +
            '<div class="rowflex" style="margin-top:10px"><span class="mini">第 ' + (p + 1) + ' / ' + Math.max(1, (d && d.totalPages) || 1) + ' 页 · 共 ' + num((d && d.totalElements) || 0) + ' 条</span>' +
            '<span style="margin-left:auto;display:flex;gap:6px">' +
            '<button class="btn sm" data-hp="' + (p - 1) + '"' + (p <= 0 ? ' disabled' : '') + '>上一页</button>' +
            '<button class="btn sm" data-hp="' + (p + 1) + '"' + (!d || d.last ? ' disabled' : '') + '>下一页</button></span></div>';
          $$('#histBody [data-hp]').forEach(el => el.onclick = () => historyModal(Number(el.dataset.hp)));
        })
        .catch(e => { const box = $('#histBody'); if (box) box.innerHTML = '<div class="mini" style="padding:14px 0">读取失败：' + esc(onlineErrText(e)) + '</div>'; });
    }
  });
}

