function tokenStamp(v) { return v ? String(v).replace('T', ' ').slice(0, 16) : '—'; }
function tokenScopeLabel(name) {
  const hit = (apiTokenScopes || []).find(x => (x.name || x[0]) === name);
  return hit ? (hit.display || hit[1] || name) : name;
}
function tokenScopeText(list) { return (list || []).map(tokenScopeLabel).join('、') || '—'; }
function tokenExpiryText(k) {
  if (!k.expiresDate) return '永久';
  if (k.expired) return '已过期 · ' + tokenStamp(k.expiresDate);
  const left = Math.ceil((new Date(k.expiresDate).getTime() - Date.now()) / 86400000);
  return tokenStamp(k.expiresDate) + (left > 0 ? ' · 剩 ' + left + ' 天' : '');
}
function tokenLocalStamp(d) {
  const p = n => String(n).padStart(2, '0');
  return d.getFullYear() + '-' + p(d.getMonth() + 1) + '-' + p(d.getDate()) + 'T' + p(d.getHours()) + ':' + p(d.getMinutes()) + ':' + p(d.getSeconds());
}
function loadTokens() {
  if (!window.LantaiRuntime) { apiTokensErr = '后端不可用'; return; }
  apiTokensBusy = true;
  Promise.all([
    LantaiRuntime.request('api/lantai/v1/api-tokens'),
    LantaiRuntime.request('api/lantai/v1/api-tokens/scopes').catch(() => null)
  ]).then(([list, scopes]) => {
    apiTokens = Array.isArray(list) ? list : [];
    if (Array.isArray(scopes) && scopes.length) apiTokenScopes = scopes;
    apiTokensErr = '';
  }).catch(e => {
    apiTokens = [];
    apiTokensErr = '令牌列表加载失败：' + onlineErrText(e);
  }).then(() => {
    apiTokensBusy = false;
    if (S.route.indexOf('/settings') === 0) render();
  });
}
