function readAny(id) {
  const b = book(id);
  if (b) return openReader(b.id);
  const s = series(id); if (!s) return toast('找不到这本书', 'err');
  if (s.online) { const bs = booksOf(s.id); return bs[0] ? openReader(bs[0].id) : toast('这个订阅还没有章节', 'info'); }
  const p = bestProgress(s.id);
  const target = p ? p.b : booksOf(s.id)[0];
  target ? openReader(target.id) : toast('这个系列还没有可读的册', 'err');
}
function copyTextValue(t) {
  const done = () => toast('已复制：' + t, 'ok');
  if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(t).then(done, () => fallback());
  return fallback();
  function fallback() {
    const ta = document.createElement('textarea');
    ta.value = t; ta.style.position = 'fixed'; ta.style.opacity = '0';
    document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); done(); } catch (e) { toast('复制失败，请手动选中：' + t, 'warn'); }
    ta.remove();
  }
}
function libOp(id, path, label) {
  const l = lib(id);
  return LantaiRuntime.request('api/v1/libraries/' + id + '/' + path, { method: 'POST' })
    .then(() => toast(label + '已提交：' + (l ? l.name : id), 'ok'))
    .catch(e => toast(label + '失败：' + onlineErrText(e), 'err'));
}
function queueScan(l) {
  if (!l) return;
  if (l.type === 'ONLINE') return toast('在线库不支持扫描：' + l.name, 'err', 3200);
  toast('正在提交扫描任务：' + l.name);
  return libOp(l.id, 'scan', '扫描');
}
