        const body = { name, scanInterval: $('#lmInt').value };
        if (root) body.root = root;
        $$('#modal [data-lm]').forEach(c => { body['scan' + c.dataset.lm.charAt(0).toUpperCase() + c.dataset.lm.slice(1)] = c.checked; });
        $$('#modal [data-lma]').forEach(c => { body[c.dataset.lma] = c.checked; });
        const one = $('#modal #lmOne');
        if (one) body.oneshotsDirectory = one.value.trim();
        const exc = $('#modal #lmExc');
        if (exc) body.scanDirectoryExclusions = exc.value.split('\n').map(s => s.trim()).filter(Boolean);
        const btn = $('#modal [data-ok]'); btn.disabled = true;
