        req.then(() => { closeModal(); return libReload(isNew ? '已建库 ' + name : '已保存 ' + name); })
          .catch(e => toast((isNew ? '建库失败：' : '保存失败：') + onlineErrText(e), 'err'))
          .then(() => { btn.disabled = false; });
